/** Trusted React renderer for this Rich Catalog component. */
import React from "react"; import {useRichComponent} from "../../../binding.js"; export function Renderer({surface,component,basePath="/"}){const {properties:p}=useRichComponent(surface,component,basePath);return <section className="anu-rich-kv">{p.title&&<h4>{p.title}</h4>}<dl>{(p.items??[]).map((x,i)=><React.Fragment key={`${x.label}-${i}`}><dt>{x.icon&&<span>{x.icon}</span>}{x.label}</dt><dd>{String(x.value)}</dd></React.Fragment>)}</dl></section>}
